/**
 * @canvas      Welcome — a single "Hello" artboard with one heading
 * @ds          maude
 * @platform    desktop
 * @artboards   hello
 * @brief       One artboard called "Hello" that shows a heading saying "Hello".
 * @stack       React 19 · TSX · Bun.build
 */

import "../system/maude/colors_and_type.css";
import "../system/maude/preview/_components.css";
import { DesignCanvas, DCSection, DCArtboard } from "@maude/canvas-lib";

export default function Welcome() {
  return (
    <DesignCanvas>
      <DCSection id="welcome" title="Welcome">
        <DCArtboard id="hello" label="Hello" width={800} height={600}>
          <main
            className="maude"
            data-theme="dark"
            style={{
              width: "100%",
              height: "100%",
              display: "grid",
              placeItems: "center",
              background: "var(--bg)",
              color: "var(--fg)",
            }}
          >
            <h1 style={{ margin: 0 }}>Hello</h1>
          </main>
        </DCArtboard>
      </DCSection>
    </DesignCanvas>
  );
}

{
  "title": "Welcome",
  "subtitle": "A single Hello artboard",
  "brief": "One artboard called \"Hello\" that shows a heading saying \"Hello\".",
  "platform": "desktop",
  "designSystem": "maude",
  "kind": "canvas",
  "sections": [
    {
      "id": "welcome",
      "title": "Welcome"
    }
  ],
  "artboards": [
    {
      "id": "hello",
      "label": "Hello"
    }
  ],
  "layout": {
    "artboards": [
      {
        "id": "hello",
        "x": 0,
        "y": 0
      }
    ]
  }
}

